+
+// Disposable SET-759 measurement only; never applied to the delivery branch.
+type Set759Timing = { start: number; phases: { name: string; ms: number }[] };
+async function set759Timed<T>(timing: Set759Timing | undefined, name: string, fn: () => Promise<T>): Promise<T> {
+  if (!timing) return fn();
+  const start = Bun.nanoseconds();
+  try { return await fn(); }
+  finally { timing.phases.push({ name, ms: (Bun.nanoseconds() - start) / 1e6 }); }
+}
+function set759TimedSync<T>(timing: Set759Timing | undefined, name: string, fn: () => T): T {
+  if (!timing) return fn();
+  const start = Bun.nanoseconds();
+  try { return fn(); }
+  finally { timing.phases.push({ name, ms: (Bun.nanoseconds() - start) / 1e6 }); }
+}
